#!/usr/bin/env python3
"""Minimal Go board helper for validating tsumego positions."""
from __future__ import annotations

COLS = "abcdefghijklmnopqrs"

def parse_coord(s: str) -> tuple[int, int]:
    c, r = s.lower()
    return COLS.index(c), COLS.index(r)

def fmt(x: int, y: int) -> str:
    return f"{COLS[x]}{COLS[y]}"

class Board:
    def __init__(self):
        self.grid = [[None] * 19 for _ in range(19)]  # 'B'/'W'/None

    def copy(self):
        b = Board()
        b.grid = [row[:] for row in self.grid]
        return b

    def place_setup(self, black: list[str], white: list[str]):
        for s in black:
            x, y = parse_coord(s)
            self.grid[y][x] = "B"
        for s in white:
            x, y = parse_coord(s)
            self.grid[y][x] = "W"

    def in_bounds(self, x, y):
        return 0 <= x < 19 and 0 <= y < 19

    def neighbors(self, x, y):
        for dx, dy in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            nx, ny = x + dx, y + dy
            if self.in_bounds(nx, ny):
                yield nx, ny

    def group(self, x, y):
        color = self.grid[y][x]
        if not color:
            return set(), set()
        stones = set()
        libs = set()
        stack = [(x, y)]
        seen = set()
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in seen:
                continue
            seen.add((cx, cy))
            stones.add((cx, cy))
            for nx, ny in self.neighbors(cx, cy):
                v = self.grid[ny][nx]
                if v is None:
                    libs.add((nx, ny))
                elif v == color and (nx, ny) not in seen:
                    stack.append((nx, ny))
        return stones, libs

    def remove_group(self, stones):
        for x, y in stones:
            self.grid[y][x] = None

    def play(self, color: str, coord: str) -> bool:
        """Play a move. Returns False if illegal."""
        x, y = parse_coord(coord)
        if self.grid[y][x] is not None:
            return False
        self.grid[y][x] = color
        opp = "W" if color == "B" else "B"
        captured = []
        for nx, ny in self.neighbors(x, y):
            if self.grid[ny][nx] == opp:
                stones, libs = self.group(nx, ny)
                if not libs:
                    captured.extend(stones)
        for sx, sy in captured:
            self.grid[sy][sx] = None
        stones, libs = self.group(x, y)
        if not libs:
            # suicide
            self.grid[y][x] = None
            for sx, sy in captured:
                self.grid[sy][sx] = opp
            return False
        return True

    def show(self, x0=0, y0=0, x1=18, y1=18):
        lines = []
        header = "  " + " ".join(COLS[x] for x in range(x0, x1 + 1))
        lines.append(header)
        for y in range(y0, y1 + 1):
            row = [COLS[y] + " "]
            for x in range(x0, x1 + 1):
                v = self.grid[y][x]
                row.append("." if v is None else v)
            lines.append(" ".join(row) if False else COLS[y] + " " + " ".join(
                ("." if self.grid[y][x] is None else self.grid[y][x]) for x in range(x0, x1 + 1)
            ))
        return "\n".join(lines)

    def liberties_of_color(self, color):
        seen = set()
        out = []
        for y in range(19):
            for x in range(19):
                if self.grid[y][x] == color and (x, y) not in seen:
                    stones, libs = self.group(x, y)
                    seen |= stones
                    out.append((sorted(fmt(a, b) for a, b in stones), sorted(fmt(a, b) for a, b in libs)))
        return out


def test(name, black, white, moves, region=(0, 0, 10, 10)):
    b = Board()
    b.place_setup(black, white)
    print(f"\n=== {name} ===")
    x0, y0, x1, y1 = region
    print(b.show(x0, y0, x1, y1))
    print("Black groups:", b.liberties_of_color("B"))
    print("White groups:", b.liberties_of_color("W"))
    for color, coord in moves:
        ok = b.play(color, coord)
        print(f"Play {color}[{coord}]: {'ok' if ok else 'ILLEGAL'}")
        print(b.show(x0, y0, x1, y1))
        print("Black groups:", b.liberties_of_color("B"))
        print("White groups:", b.liberties_of_color("W"))


if __name__ == "__main__":
    # Problem 01 draft: White to capture black corner group in atari by filling last liberty
    # But black can live if white fails - black expands
    test(
        "P1 draft",
        black=["ar", "br", "bs"],
        white=["aq", "bq", "cq", "cr", "cs", "ds"],
        moves=[("W", "as")],
        region=(0, 14, 5, 18),
    )

